{"path":"extensions/perplexity/perplexity.ts","content":"/**
 * Perplexity API client.
 *
 * Perplexity exposes an OpenAI-compatible chat completions endpoint at
 * https://api.perplexity.ai/chat/completions. Each response carries a
 * top-level `citations` array (URLs) and optionally `search_results`
 * ({ title, url, date }) with richer metadata.
 *
 * Pro plan models: sonar, sonar-pro (default), sonar-reasoning,
 * sonar-reasoning-pro, sonar-deep-research.
 */

const PERPLEXITY_ENDPOINT = "https://api.perplexity.ai/chat/completions";

export interface PerplexitySource {
	title: string;
	url: string;
}

export interface PerplexityMessage {
	role: "system" | "user" | "assistant";
	content: string;
}

export interface PerplexityResult {
	content: string;
	citations: PerplexitySource[];
}

export interface PerplexityModelInfo {
	id: string;
	label: string;
	deepResearch: boolean;
}

/**
 * Models offered on the Perplexity Pro plan. `deepResearch` models are slow
 * (1-3 min) but produce long, heavily-cited syntheses.
 */
export const PERPLEXITY_MODELS: PerplexityModelInfo[] = [
	{ id: "sonar", label: "sonar", deepResearch: false },
	{ id: "sonar-pro", label: "sonar-pro", deepResearch: false },
	{ id: "sonar-reasoning", label: "sonar-reasoning", deepResearch: false },
	{ id: "sonar-reasoning-pro", label: "sonar-reasoning-pro", deepResearch: false },
	{ id: "sonar-deep-research", label: "sonar-deep-research", deepResearch: true },
];

export function getPerplexityApiKey(): string {
	const key = process.env.PERPLEXITY_API_KEY;
	if (!key) {
		throw new Error(
			"PERPLEXITY_API_KEY is not set. Add it to your environment (e.g. shell rc or .env).",
		);
	}
	return key;
}

function mergeSources(
	citations: unknown,
	searchResults: unknown,
): PerplexitySource[] {
	const byUrl = new Map<string, PerplexitySource>();

	if (Array.isArray(searchResults)) {
		for (const r of searchResults) {
			if (r && typeof r === "object") {
				const url = String((r as { url?: unknown }).url ?? "").trim();
				if (!url) continue;
				const title = String((r as { title?: unknown }).title ?? url);
				byUrl.set(url, { title: title || url, url });
			}
		}
	}

	if (Array.isArray(citations)) {
		for (const c of citations) {
			if (typeof c === "string") {
				const url = c.trim();
				if (url && !byUrl.has(url)) byUrl.set(url, { title: url, url });
			} else if (c && typeof c === "object") {
				const url = String((c as { url?: unknown }).url ?? "").trim();
				if (!url) continue;
				const title = String((c as { title?: unknown }).title ?? url);
				if (!byUrl.has(url)) byUrl.set(url, { title: title || url, url });
			}
		}
	}

	return Array.from(byUrl.values());
}

interface ChatCompletionChunk {
	choices?: Array<{ delta?: { content?: string | null }; message?: { content?: string } }>;
	citations?: unknown;
	search_results?: unknown;
}

/**
 * Non-streaming search. Used by the `web_search` / `fetch_content` /
 * `get_search_content` tools.
 */
export async function searchPerplexity(
	messages: PerplexityMessage[],
	model: string,
	options: { signal?: AbortSignal; maxTokens?: number } = {},
): Promise<PerplexityResult> {
	const apiKey = getPerplexityApiKey();
	const res = await fetch(PERPLEXITY_ENDPOINT, {
		method: "POST",
		headers: {
			Authorization: `Bearer ${apiKey}`,
			"Content-Type": "application/json",
			Accept: "application/json",
		},
		body: JSON.stringify({
			model,
			messages,
			stream: false,
			...(options.maxTokens ? { max_tokens: options.maxTokens } : {}),
		}),
		signal: options.signal,
	});

	if (!res.ok) {
		const text = await res.text().catch(() => "");
		throw new Error(`Perplexity API ${res.status}: ${text || res.statusText}`);
	}

	const data = (await res.json()) as ChatCompletionChunk;
	const content = data.choices?.[0]?.message?.content ?? "";
	return { content, citations: mergeSources(data.citations, data.search_results) };
}

export interface StreamCallbacks {
	onDelta?: (chunk: string) => void;
	onCitations?: (sources: PerplexitySource[]) => void;
}

/**
 * Streaming search. Calls `onDelta` for each content chunk as it arrives and
 * `onCitations` whenever the API publishes sources. Returns the final result.
 */
export async function streamPerplexity(
	messages: PerplexityMessage[],
	model: string,
	options: { signal?: AbortSignal; maxTokens?: number } & StreamCallbacks = {},
): Promise<PerplexityResult> {
	const apiKey = getPerplexityApiKey();
	const res = await fetch(PERPLEXITY_ENDPOINT, {
		method: "POST",
		headers: {
			Authorization: `Bearer ${apiKey}`,
			"Content-Type": "application/json",
			Accept: "text/event-stream",
		},
		body: JSON.stringify({
			model,
			messages,
			stream: true,
			...(options.maxTokens ? { max_tokens: options.maxTokens } : {}),
		}),
		signal: options.signal,
	});

	if (!res.ok || !res.body) {
		const text = await res.text().catch(() => "");
		throw new Error(`Perplexity API ${res.status}: ${text || res.statusText}`);
	}

	let content = "";
	let citations: PerplexitySource[] = [];
	let emittedCitations = false;
	const reader = res.body.getReader();
	const decoder = new TextDecoder();
	let buffer = "";

	const emitCitations = (sources: PerplexitySource[]) => {
		if (sources.length === 0) return;
		citations = sources;
		if (!emittedCitations) {
			options.onCitations?.(sources);
			emittedCitations = true;
		} else {
			options.onCitations?.(sources);
		}
	};

	for (;;) {
		const { done, value } = await reader.read();
		if (done) break;
		buffer += decoder.decode(value, { stream: true });

		let nl: number;
		while ((nl = buffer.indexOf("\n")) >= 0) {
			const line = buffer.slice(0, nl).trim();
			buffer = buffer.slice(nl + 1);
			if (!line || !line.startsWith("data:")) continue;
			const payload = line.slice(5).trim();
			if (payload === "[DONE]") continue;
			try {
				const chunk = JSON.parse(payload) as ChatCompletionChunk;
				const delta = chunk.choices?.[0]?.delta?.content;
				if (delta) {
					content += delta;
					options.onDelta?.(delta);
				}
				if (chunk.citations || chunk.search_results) {
					emitCitations(mergeSources(chunk.citations, chunk.search_results));
				}
			} catch {
				// ignore malformed keepalive / partial lines
			}
		}
	}

	return { content, citations };
}
"}
{"path":"extensions/perplexity/index.ts","content":"/**
 * Perplexity extension for pi.
 *
 * Two pieces:
 *   1. Web tools (`web_search`, `fetch_content`, `get_search_content`) —
 *      Perplexity-backed stand-ins for the `pi-web-access` tools that
 *      pi-subagents' `researcher` and `context-builder` agents expect.
 *   2. `/research` command — opens an interactive research panel that runs a
 *      back-and-forth Perplexity session *outside* your main context window,
 *      then builds a recap you can shape and inject into your pi thread.
 *
 * Requires PERPLEXITY_API_KEY in your environment.
 */

import { complete, type Message } from "@earendil-works/pi-ai/compat";
import type { ExtensionAPI, ExtensionCommandContext } from "@earendil-works/pi-coding-agent";
import {
	DEFAULT_MAX_BYTES,
	formatSize,
	getMarkdownTheme,
	truncateHead,
} from "@earendil-works/pi-coding-agent";
import { Markdown, Text } from "@earendil-works/pi-tui";
import { StringEnum } from "@earendil-works/pi-ai";
import { Type } from "typebox";
import {
	type PerplexityMessage,
	type PerplexitySource,
	searchPerplexity,
} from "./perplexity.ts";
import {
	type ResearchResult,
	type TranscriptTurn,
	ResearchPanel,
} from "./research-panel.ts";

const DEFAULT_SEARCH_MODEL = "sonar-pro";

function formatSources(sources: PerplexitySource[]): string {
	if (sources.length === 0) return "";
	const lines = sources.map((s, i) => `[${i + 1}] ${s.title} — ${s.url}`);
	return `\n\nSources:\n${lines.join("\n")}`;
}

/** Truncate tool output to pi's built-in byte budget, with a trailing notice. */
function truncateToolOutput(text: string): string {
	const truncation = truncateHead(text, { maxBytes: DEFAULT_MAX_BYTES });
	if (!truncation.truncated) return text;
	return (
		truncation.content +
		`\n\n[Output truncated: ${formatSize(truncation.outputBytes)} of ${formatSize(truncation.totalBytes)}. ${truncation.outputLines}/${truncation.totalLines} lines.]`
	);
}

/** Recency windows accepted by the pi-web-access-compatible `web_search` schema. */
const WEB_RECENCY_VALUES = ["day", "week", "month", "year"];

/** Normalize the `query`/`queries` params shared by the web tools. */
function normalizeWebQueries(
	query: string | undefined,
	queries: string[] | undefined,
): string[] {
	const list = Array.isArray(queries)
		? queries.filter((q): q is string => typeof q === "string" && q.trim().length > 0)
		: [];
	if (list.length === 0 && typeof query === "string" && query.trim()) {
		list.push(query.trim());
	}
	return list.map((q) => q.trim()).filter(Boolean);
}

interface WebSearchEntry {
	query: string;
	content: string;
	citations: PerplexitySource[];
}

interface WebSearchHint {
	recencyFilter?: string;
	domainFilter?: string[];
	numResults?: number;
	includeContent: boolean;
}

/** Build Perplexity messages for a `web_search` query, folding in best-effort hints. */
function buildWebSearchMessages(query: string, hint: WebSearchHint): PerplexityMessage[] {
	const extras: string[] = [];
	if (hint.recencyFilter) extras.push(`Focus on results from the last ${hint.recencyFilter}.`);
	if (hint.domainFilter && hint.domainFilter.length) {
		const include = hint.domainFilter.filter((d) => !d.startsWith("-"));
		const exclude = hint.domainFilter
			.filter((d) => d.startsWith("-"))
			.map((d) => d.slice(1));
		if (include.length) extras.push(`Prefer these domains: ${include.join(", ")}.`);
		if (exclude.length) extras.push(`Avoid these domains: ${exclude.join(", ")}.`);
	}
	const system = hint.includeContent
		? `You are a helpful web research assistant. Answer concisely and accurately, citing sources.${extras.length ? `\n\n${extras.join(" ")}` : ""}`
		: `You are a web search index. Return only a concise list of the most relevant source titles and URLs, one per line, no prose.${extras.length ? `\n\n${extras.join(" ")}` : ""}`;
	return [
		{ role: "system", content: system },
		{ role: "user", content: query },
	];
}

/** Render per-query `web_search` results as a single text block. */
function formatWebSearchResults(
	results: WebSearchEntry[],
	includeContent: boolean,
): string {
	const blocks = results.map((r, i) => {
		const header = `## Query${results.length > 1 ? ` ${i + 1}` : ""}: ${r.query}`;
		const sourceLines = r.citations
			.map((s, j) => `[${j + 1}] ${s.title} — ${s.url}`)
			.join("\n");
		if (includeContent) {
			return `${header}\n\n${r.content.trim() || "(no answer)"}${sourceLines ? `\n\nSources:\n${sourceLines}` : ""}`;
		}
		return `${header}\n${sourceLines || "(no sources)"}`;
	});
	return blocks.join("\n\n---\n\n");
}

/** Build Perplexity messages for `fetch_content` — synthesize page content from a URL. */
function buildFetchContentMessages(url: string, prompt?: string): PerplexityMessage[] {
	const system =
		"You are a content extraction assistant. Read the page at the given URL and respond to the user's instruction. If the page cannot be fetched, say so and answer from what you know, citing sources.";
	const instruction =
		prompt?.trim() || "Summarize the main content of this page, preserving key facts and structure.";
	return [
		{ role: "system", content: system },
		{ role: "user", content: `URL: ${url}\n\n${instruction}` },
	];
}

const RECAP_SYSTEM_PROMPT = `You are a research summarizer. Given a transcript of a research session (user questions and assistant answers with sources), produce a clean, self-contained recap that someone can drop into a working context to get up to speed.

Use exactly this structure:

## Topic
A one-line description of what was researched.

## Key Findings
3-6 concise bullets, each a self-contained fact. Inline citations as [n].

## Sources
A numbered list of URLs actually referenced in the findings (skip unreferenced ones). Format: [n] title — url

## Open Questions / Next Steps
2-4 bullets of gaps or logical next steps.

Be concise and factual. Do not add preamble. Do not invent facts not present in the transcript.`;

function transcriptToText(turns: TranscriptTurn[]): string {
	const parts: string[] = [];
	for (const turn of turns) {
		const label = turn.role === "user" ? "User" : "Perplexity";
		let block = `${label}: ${turn.text}`;
		if (turn.role === "assistant" && turn.citations && turn.citations.length > 0) {
			block += "\nCitations:";
			turn.citations.forEach((c, i) => {
				block += `\n[${i + 1}] ${c.title} — ${c.url}`;
			});
		}
		parts.push(block);
	}
	return parts.join("\n\n");
}

export default function (pi: ExtensionAPI) {
	// ---- 1b. web_search / fetch_content / get_search_content ------------
	//
	// pi-subagents' `researcher` and `context-builder` agents reference a
	// `web_search` tool (the `researcher` also wants `fetch_content` and
	// `get_search_content`). Those names normally come from the
	// `pi-web-access` package. pi-subagents validates every tool listed in an
	// agent's `tools:` frontmatter against the live tool registry and fails
	// the run if any is missing — so without these shims, subagent runs that
	// list `web_search` abort with an "unavailable tool" error.
	//
	// These three tools are backed by the same Perplexity client as the
	// `/research` panel. They accept pi-web-access-compatible params
	// (`query`/`queries`, `numResults`, `recencyFilter`, `domainFilter`, …)
	// as best-effort hints, since Perplexity synthesizes answers rather than
	// returning raw result snippets.

	const WebSearchParams = Type.Object({
		query: Type.Optional(
			Type.String({ description: "Single search query. Prefer `queries` for multiple angles." }),
		),
		queries: Type.Optional(
			Type.Array(Type.String(), {
				description: "Batch of search queries; each gets its own answer + sources.",
			}),
		),
		numResults: Type.Optional(
			Type.Number({
				description: "Result-count hint (Perplexity controls citation count).",
				default: 5,
			}),
		),
		recencyFilter: Type.Optional(
			StringEnum(WEB_RECENCY_VALUES, { description: "Bias results toward a recency window." }),
		),
		domainFilter: Type.Optional(
			Type.Array(Type.String(), {
				description: "Domains to include (prefix with `-` to exclude). Best-effort hint.",
			}),
		),
		includeContent: Type.Optional(
			Type.Boolean({
				description: "Return synthesized answers (true, default) or just source lists (false).",
				default: true,
			}),
		),
	});

	pi.registerTool({
		name: "web_search",
		label: "Web Search",
		description:
			"Search the web and return answers with numbered sources. Backed by Perplexity. Accepts a single `query` or a `queries` array (preferred for covering multiple angles). Use for fresh information, current events, library/API docs, or anything not in local files. Cite the returned source numbers inline. This is the Perplexity-backed stand-in for the `web_search` tool that pi-subagents (researcher, context-builder) expect from pi-web-access.",
		promptSnippet: "Web search (Perplexity) — `queries` array supported",
		promptGuidelines: [
			"Pass 2-4 distinct angles via `queries` rather than one generic query.",
			"Cite the returned source numbers inline. Returns synthesized answers, not raw result snippets.",
		],
		parameters: WebSearchParams,
		async execute(_toolCallId, params, signal) {
			const queries = normalizeWebQueries(params.query, params.queries);
			if (!queries.length) {
				return {
					content: [{ type: "text", text: "web_search: provide a `query` or `queries`." }],
					details: {
						model: DEFAULT_SEARCH_MODEL,
						queries,
						results: [] as WebSearchEntry[],
						sources: [] as PerplexitySource[],
					},
				};
			}
			const includeContent = params.includeContent !== false;
			const results = await Promise.all(
				queries.map(async (q) => {
					const messages = buildWebSearchMessages(q, {
						recencyFilter: params.recencyFilter,
						domainFilter: params.domainFilter,
						numResults: params.numResults,
						includeContent,
					});
					const result = await searchPerplexity(messages, DEFAULT_SEARCH_MODEL, { signal });
					return { query: q, ...result };
				}),
			);
			const text = formatWebSearchResults(results, includeContent);
			return {
				content: [{ type: "text", text: truncateToolOutput(text) }],
				details: {
					model: DEFAULT_SEARCH_MODEL,
					queries,
					results,
					sources: results.flatMap((r) => r.citations),
				},
			};
		},
		renderCall(args, theme) {
			const queries = normalizeWebQueries(
				args.query as string | undefined,
				args.queries as string[] | undefined,
			);
			const first = queries[0] ?? "";
			const preview = first.length > 60 ? `${first.slice(0, 60)}…` : first;
			const more = queries.length > 1 ? ` +${queries.length - 1}` : "";
			return new Text(
				theme.fg("toolTitle", theme.bold("web_search ")) +
					theme.fg("muted", `[${DEFAULT_SEARCH_MODEL}] `) +
					theme.fg("dim", preview + more),
				0,
				0,
			);
		},
		renderResult(result, { expanded }, theme) {
			const text = result.content[0]?.type === "text" ? result.content[0].text : "(no output)";
			if (expanded) return new Markdown(text, 0, 0, getMarkdow…1868 tokens truncated… = new ResearchPanel(tui, theme, {
					synthesize: (turns, signal) => synthesizeRecap(ctx, turns, signal),
					done,
				});
				if (initialQuery.trim()) panel.prefill(initialQuery.trim());
				return panel;
			});

			if (!result?.recap) {
				// cancelled
				return;
			}

			// Recap requested: the panel already synthesized using the pi model
			// (during which it showed a "building recap…" status). Now let the
			// user shape the recap in an editor before it touches context.
			let draft = result.recapText;
			if (!draft.trim()) {
				ctx.ui.notify("Recap came back empty", "warning");
				return;
			}

			const edited = await ctx.ui.editor(
				"Research recap — review/edit, then submit to inject into context",
				draft,
			);

			if (edited === undefined || !edited.trim()) {
				ctx.ui.notify("Recap discarded", "info");
				return;
			}

			// (a) Load into the editor for the user to send themselves — no
			// surprise context injection or cost.
			ctx.ui.setEditorText(edited.trim());
			ctx.ui.notify("Recap loaded — submit when ready.", "info");
		},
	});
}
"}
{"path":"extensions/perplexity/README.md","content":"# Perplexity Extension

Web search and interactive research via the [Perplexity API](https://docs.perplexity.ai/),
designed to keep raw search traffic **out of your main pi context window**.

Two pieces:

1. **Web tools (`web_search`, `fetch_content`, `get_search_content`)** —
   Perplexity-backed stand-ins for the [`pi-web-access`](https://github.com/nicobailon/pi-web-access)
   tools that pi-subagents' `researcher` and `context-builder` agents list in
   their `tools:` frontmatter. Without them, subagent runs that reference
   `web_search` fail with an "unavailable tool" error. They keep raw search
   traffic out of your main context by synthesizing answers (with cited sources)
   instead of returning raw result snippets.
2. **`/research` command** — an interactive, full-screen research panel where you
   run a back-and-forth Perplexity session (queries + streamed answers + sources),
   then build a **recap** you can shape in an editor and inject into your main
   thread. All intermediate search content stays inside the panel and is discarded
   unless you build a recap.

## Review and proposed redesign

See [the review and implementation proposal](./REVIEW-AND-IMPLEMENTATION-PLAN.md)
for the evidence-tool contract gaps, proposed source snapshots and claim-evidence
workflow, package-owned research agents, and the Sonar-to-Agent/Search API migration.
This is a proposal only; the runtime behavior described below has not changed.

## Setup

Requires a Perplexity Pro plan and an API key in your environment:

```sh
export PERPLEXITY_API_KEY=pplx-...
```

The extension is auto-discovered from `~/.pi/agent/extensions/perplexity/` (global).
Reload after changes with `/reload`.

## The web tools

Three Perplexity-backed tools that satisfy the `web_search` / `fetch_content` /
`get_search_content` contract pi-subagents expect from `pi-web-access`. The
parent agent can call them too. All use the `sonar-pro` model; output is
truncated to 50 KB (built-in pi limit), with sources appended as a numbered
list.

### `web_search`

Search the web and return answers with numbered sources. Accepts a single
`query` or a `queries` array (preferred for covering multiple angles in one
call — each query gets its own answer + sources).

| Parameter        | Type       | Notes                                                          |
|------------------|------------|----------------------------------------------------------------|
| `query`          | string?    | A single search query. Prefer `queries` for multiple angles.   |
| `queries`        | string[]?  | Batch of queries; each gets its own answer + sources.          |
| `numResults`     | number?    | Result-count hint (Perplexity controls citation count).        |
| `recencyFilter`  | enum?      | `day` \| `week` \| `month` \| `year` — bias toward recency.   |
| `domainFilter`   | string[]?  | Domains to include (prefix with `-` to exclude). Best-effort. |
| `includeContent` | boolean?   | `true` (default) returns synthesized answers; `false` returns only source lists. |

### `fetch_content`

Read a URL and return a synthesized summary of its content. Perplexity
(`sonar-pro`) fetches the page and answers an optional `prompt` about it.

| Parameter   | Type     | Notes                                                         |
|-------------|----------|---------------------------------------------------------------|
| `url`       | string   | URL to read (http/https/GitHub/PDF).                          |
| `prompt`    | string?  | Instruction for what to extract or answer about the page.     |
| `maxTokens` | number?  | Cap on returned content length.                               |

### `get_search_content`

Search the web and retrieve synthesized content in one step: runs the query,
reads the top result pages, and synthesizes a thorough answer drawing on their
content. Same param shape as `web_search`, plus an optional `prompt` and
`maxTokens`.

> These tools synthesize answers rather than returning raw result snippets.
> `fetch_content` does not clone repos or parse PDFs/YouTube like
> `pi-web-access` does — install that package alongside if you need full URL
> fetching. For most research tasks the Perplexity-backed synthesis is enough.

## The `/research` panel

```
┌ Perplexity Research · sonar-pro ─────────────────────────────────────────┐
│ ❯ your first query                                                       │
│                                                                          │
│ …streamed answer with markdown…                                         │
│ ─────────────────────────────────                                        │
│ [1] Source title https://…                                               │
│                                                                          │
│ …more turns…                                                             │
├────────────────────────────────────────────────────────── 1-12/12 ───────┤
│ ▸ your next query…                                                       │
└ ⏎ send · ctrl+p model · ctrl+t deep-research · ctrl+r recap · ↑↓ scroll · esc close ┘
```

### Keys

| Key            | Action                                                        |
|----------------|---------------------------------------------------------------|
| `Enter`        | Send the current query (answer streams into the transcript). |
| `Ctrl+P`       | Cycle the Perplexity model (sonar → sonar-pro → …).           |
| `Ctrl+T`       | Toggle deep-research mode (`sonar-deep-research`; slower, heavily-cited). |
| `Ctrl+R`       | Build a recap from the transcript (closes the panel).         |
| `Up` / `Down`  | Scroll the transcript (auto-scrolls to bottom while searching). |
| `PgUp` / `PgDn`| Scroll by a page.                                             |
| `Esc` / `Ctrl+C` | Cancel a running search; if idle, close the panel (discards everything). |

### Recap flow (the important part)

When you press `Ctrl+R`:

1. The transcript is sent to your **current pi model** (e.g. Claude) with a prompt
   that produces a structured recap:
   ```
   ## Topic
   ## Key Findings   (3-6 bullets, inline [n] citations)
   ## Sources        (only URLs actually referenced)
   ## Open Questions / Next Steps
   ```
2. The recap opens in a pi editor (`ctx.ui.editor`) for you to **shape** — cut,
   rewrite, add notes. Nothing has entered your context yet.
3. On submit, the recap is loaded into your main input editor via
   `ctx.ui.setEditorText()`. You press `Enter` to inject it — no surprise cost,
   no automatic context pollution.

Everything else (raw answers, intermediate queries, full citation lists) is
discarded. Only the recap you approve reaches your main thread.

## Why not a subprocess (like the subagent example)?

The isolation here is *logical*, not process-level: the research loop runs in a
custom TUI component and the only exit point is the shaped recap. That keeps the
implementation simple (one HTTP client, no child `pi` processes) while still
guaranteeing nothing leaks into your session until you say so. If you later want
the model itself to drive follow-up searches autonomously, the same
`streamPerplexity` client can be wrapped in a subagent-style child process.

## Files

- `perplexity.ts` — API client (OpenAI-compatible chat completions, streaming
  SSE parsing, citation/source merging).
- `research-panel.ts` — `ResearchPanel` custom TUI component (scrollable
  transcript, embedded `Input`, model/deep-research toggles, recap trigger).
- `index.ts` — registers the `web_search` / `fetch_content` / `get_search_content`
  tools and the `/research` command, plus the recap synthesis prompt.
"}
